{{-- Dropdown styles and keyboard handling shared by the language switcher, the app switcher and the account menu. --}}
@once
<style nonce="{{ \Hop\Ui\Assets::nonce() }}">
.hop-switcher{position:relative;flex:none;color:inherit}.hop-switcher>summary{list-style:none;display:grid;place-items:center;cursor:pointer;width:36px;height:36px;border-radius:12px}.hop-switcher>summary::-webkit-details-marker{display:none}.hop-switcher>summary:hover,.hop-switcher[open]>summary{background:rgb(99 102 241 / .12)}.hop-switcher-panel{position:absolute;inset-inline-end:0;top:calc(100% + 12px);width:260px;max-width:calc(100vw - 24px);padding:12px;border:1px solid #cbd5e1;border-radius:20px;background:#fff;color:#172033;box-shadow:0 18px 55px #0f172a26;z-index:80}.hop-switcher-panel>strong{display:block;padding:6px 10px;font-size:13px}.hop-switcher-panel>a{display:flex;align-items:center;gap:12px;padding:10px;border-radius:12px;font-size:14px;text-decoration:none;color:inherit}.hop-switcher-panel>a:hover,.hop-switcher-panel>a[aria-current]{background:#6366f115}.hop-switcher-panel img{object-fit:contain}.hop-langmenu .hop-switcher-panel{width:230px;padding:6px}.hop-langmenu .hop-switcher-panel>a{justify-content:space-between;gap:12px;padding:8px 10px;border-radius:9px}.hop-langmenu .hop-switcher-panel>a small{color:#64748b;font:500 11px ui-monospace,'JetBrains Mono',monospace}.dark .hop-langmenu .hop-switcher-panel>a small{color:#94a3b8}.hop-switcher :focus-visible{outline:2px solid #6366f1;outline-offset:3px}.dark .hop-switcher-panel{background:#151b2b;color:#f1f5f9;border-color:#394155}@media(max-width:480px){.hop-switcher-panel{position:fixed;inset-inline:12px;top:78px;width:auto;max-width:none}}
</style>
<script nonce="{{ \Hop\Ui\Assets::nonce() }}">
document.addEventListener('keydown',function(e){document.querySelectorAll('[data-hop-switcher][open]').forEach(function(d){if(e.key==='Escape'){d.open=false;d.querySelector('summary').focus();e.preventDefault();}else if(d.contains(e.target)&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){var links=Array.from(d.querySelectorAll('a')),i=links.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?links.length-1:e.key==='ArrowDown'?(i+1)%links.length:(i<=0?links.length:i)-1;links[i]?.focus();e.preventDefault();}});});
document.addEventListener('click',function(e){document.querySelectorAll('[data-hop-switcher][open]').forEach(function(d){if(!d.contains(e.target))d.open=false;});});
</script>
@endonce

